#!/bin/sh
# SPDX-FileCopyrightText: 2026 VectoDE
# SPDX-License-Identifier: GPL-3.0-or-later
# Assembles the GitHub Pages site into build/pages/:
#   /        start page (site/index.html, site/home.css)
#   /brand/  brand guide and all assets from branding/ (without the generators in branding/tools/)
#   /api/    OpenAPI description of the REST API (docs/cloud/api.openapi.yaml)
# Every link in the output is relative, so the site works under any base path such as /VectolynCloud/.
# The brand guide itself is generated by branding/tools/gen_v3.py; this script only copies it.
set -eu

root=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
out="$root/build/pages"

rm -rf "$out"
mkdir -p "$out/brand" "$out/api"
cp "$root/site/index.html" "$root/site/home.css" "$out/"
cp "$root/docs/cloud/api.openapi.yaml" "$out/api/openapi.yaml"
(cd "$root/branding" && tar -cf - --exclude=./tools .) | (cd "$out/brand" && tar -xf -)

echo "Site written to $out"
